global.schema:
type HlskPlanState {
  name: String!
  activeUnitId: OID!
  units: [HlskUnit!]!
  settings: HlskSettings!
  nextFixtureNumber: Int!
}

type HlskUnit {
  id: OID!
  name: String!
  level: Int!
  background: PlanBackground
  rooms: [HlskRoom!]
  fixtures: [HlskFixture!]!
  pipeRoutes: [PipeRoute!]!
  ductRoutes: [DuctRoute!]!
  risers: [Riser!]!
}

type HlskRoom {
  id: OID!
  name: String!
  points: [Position!]!
  fillColor: String
  labelX: Float!
  labelY: Float!
  locked: Boolean
}

type PlanBackground {
  dataUrl: String
  widthCm: Float
  heightCm: Float
  x: Float!
  y: Float!
  scale: Float!
  opacity: Float!
  rotation: Float!
  locked: Boolean!
}

type Position {
  x: Float!
  y: Float!
}

type HlskFixture {
  id: OID!
  kind: String!
  discipline: String!
  name: String!
  position: Position!
  rotation: Float!
  roomId: String
  mountHeightCm: Float
  notes: String
  locked: Boolean
}

type PipeRoute {
  id: OID!
  kind: String!
  points: [Position!]!
  diameterMm: Float!
  slopePercent: Float
  insulation: Boolean
  notes: String
}

type DuctRoute {
  id: OID!
  kind: String!
  points: [Position!]!
  widthMm: Float!
  heightMm: Float!
  airflowM3h: Float
  notes: String
}

type Riser {
  id: OID!
  kind: String!
  x: Float!
  y: Float!
  label: String
  notes: String
}

type HlskSettings {
  showLabels: Boolean!
  showMountHeights: Boolean!
  pipeDiameterMm: Float!
}

input PositionInput {
  x: Float!
  y: Float!
}

input RoomInput {
  id: OID!
  name: String!
  points: [PositionInput!]!
  fillColor: String
  labelX: Float!
  labelY: Float!
  locked: Boolean
}

input BackgroundInput {
  dataUrl: String
  widthCm: Float
  heightCm: Float
  x: Float!
  y: Float!
  scale: Float!
  opacity: Float!
  rotation: Float!
  locked: Boolean!
}

input FixtureInput {
  id: OID!
  kind: String!
  discipline: String!
  name: String!
  position: PositionInput!
  rotation: Float!
  roomId: String
  mountHeightCm: Float
  notes: String
  locked: Boolean
}

input PipeRouteInput {
  id: OID!
  kind: String!
  points: [PositionInput!]!
  diameterMm: Float!
  slopePercent: Float
  insulation: Boolean
  notes: String
}

input DuctRouteInput {
  id: OID!
  kind: String!
  points: [PositionInput!]!
  widthMm: Float!
  heightMm: Float!
  airflowM3h: Float
  notes: String
}

input RiserInput {
  id: OID!
  kind: String!
  x: Float!
  y: Float!
  label: String
  notes: String
}

input AddUnitInput { id: OID! name: String! level: Int! }
input UpdateUnitInput { id: OID! name: String level: Int }
input RemoveUnitInput { id: OID! }
input AddRoomInput { unitId: OID! room: RoomInput! }
input UpdateRoomInput { unitId: OID! id: OID! name: String fillColor: String points: [PositionInput!] labelX: Float labelY: Float locked: Boolean }
input RemoveRoomInput { unitId: OID! id: OID! }
input AddFixtureInput { unitId: OID! fixture: FixtureInput! }
input UpdateFixtureInput { unitId: OID! id: OID! kind: String name: String discipline: String position: PositionInput rotation: Float roomId: String mountHeightCm: Float notes: String locked: Boolean }
input RemoveFixtureInput { unitId: OID! id: OID! }
input AddPipeRouteInput { unitId: OID! route: PipeRouteInput! }
input UpdatePipeRouteInput { unitId: OID! id: OID! kind: String points: [PositionInput!] diameterMm: Float slopePercent: Float insulation: Boolean notes: String }
input RemovePipeRouteInput { unitId: OID! id: OID! }
input AddDuctRouteInput { unitId: OID! route: DuctRouteInput! }
input UpdateDuctRouteInput { unitId: OID! id: OID! kind: String points: [PositionInput!] widthMm: Float heightMm: Float airflowM3h: Float notes: String }
input RemoveDuctRouteInput { unitId: OID! id: OID! }
input AddRiserInput { unitId: OID! riser: RiserInput! }
input UpdateRiserInput { unitId: OID! id: OID! kind: String x: Float y: Float label: String notes: String }
input RemoveRiserInput { unitId: OID! id: OID! }
input SetProjectNameInput { name: String! }
input SetActiveUnitInput { unitId: OID! }
input SetUnitBackgroundInput { unitId: OID! background: BackgroundInput! }
input UpdateUnitBackgroundInput { unitId: OID! dataUrl: String widthCm: Float heightCm: Float x: Float y: Float scale: Float opacity: Float rotation: Float locked: Boolean }
input UpdateSettingsInput { showLabels: Boolean showMountHeights: Boolean pipeDiameterMm: Float }

operations.reducer:
if (!action.input.name.trim())
  throw new InvalidNameError("A plan needs a name");
state.name = action.input.name;

if (!state.units.some((u) => u.id === action.input.unitId))
  throw new UnknownUnitError("Unknown unit");
state.activeUnitId = action.input.unitId;

if (!action.input.name.trim())
  throw new InvalidUnitError("A unit needs a name");
if (!Number.isInteger(action.input.level) || action.input.level < 0)
  throw new InvalidUnitError("Level must be a non-negative integer");
if (state.units.some((u) => u.id === action.input.id))
  throw new DuplicateIdError("Unit id already exists");
state.units.push({
  id: action.input.id,
  name: action.input.name,
  level: action.input.level,
  background: null,
  rooms: [],
  fixtures: [],
  pipeRoutes: [],
  ductRoutes: [],
  risers: [],
});

const u = state.units.find((x) => x.id === action.input.id);
if (!u) throw new UnknownUnitError("Unknown unit");
if (action.input.name !== undefined && action.input.name !== null) {
  if (!action.input.name.trim()) throw new InvalidUnitError("A unit needs a name");
  u.name = action.input.name;
}
if (action.input.level !== undefined && action.input.level !== null) {
  if (!Number.isInteger(action.input.level) || action.input.level < 0)
    throw new InvalidUnitError("Level must be a non-negative integer");
  u.level = action.input.level;
}

const u = state.units.find((x) => x.id === action.input.id);
if (!u) throw new UnknownUnitError("Unknown unit");
if (state.units.length <= 1)
  throw new InvalidUnitError("At least one floor must remain");
state.units = state.units.filter((x) => x.id !== action.input.id);
if (state.activeUnitId === action.input.id)
  state.activeUnitId = state.units[0].id;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const b = action.input.background;
if (b.widthCm != null && (!Number.isFinite(b.widthCm) || b.widthCm <= 0))
  throw new InvalidUnitError("Background width must be positive");
if (b.heightCm != null && (!Number.isFinite(b.heightCm) || b.heightCm <= 0))
  throw new InvalidUnitError("Background height must be positive");
if (!Number.isFinite(b.x) || !Number.isFinite(b.y) || !Number.isFinite(b.scale) || !Number.isFinite(b.opacity) || !Number.isFinite(b.rotation))
  throw new InvalidUnitError("Background geometry must be finite");
u.background = {
  dataUrl: b.dataUrl ?? null,
  widthCm: b.widthCm ?? null,
  heightCm: b.heightCm ?? null,
  x: b.x, y: b.y, scale: b.scale, opacity: b.opacity, rotation: b.rotation,
  locked: b.locked,
};

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const i = action.input;
const b = u.background ?? { dataUrl: null, widthCm: null, heightCm: null, x: 0, y: 0, scale: 1, opacity: 1, rotation: 0, locked: false };
if (i.dataUrl !== undefined) b.dataUrl = i.dataUrl;
if (i.widthCm !== undefined) {
  if (i.widthCm !== null && (!Number.isFinite(i.widthCm) || i.widthCm <= 0)) throw new InvalidUnitError("Background width must be positive");
  b.widthCm = i.widthCm;
}
if (i.heightCm !== undefined) {
  if (i.heightCm !== null && (!Number.isFinite(i.heightCm) || i.heightCm <= 0)) throw new InvalidUnitError("Background height must be positive");
  b.heightCm = i.heightCm;
}
if (i.x !== undefined) {
  if (i.x === null || !Number.isFinite(i.x)) throw new InvalidUnitError("Background geometry must be finite");
  b.x = i.x;
}
if (i.y !== undefined) {
  if (i.y === null || !Number.isFinite(i.y)) throw new InvalidUnitError("Background geometry must be finite");
  b.y = i.y;
}
if (i.scale !== undefined) {
  if (i.scale === null || !Number.isFinite(i.scale) || i.scale <= 0) throw new InvalidUnitError("Background scale must be positive");
  b.scale = i.scale;
}
if (i.opacity !== undefined) {
  if (i.opacity === null || !Number.isFinite(i.opacity)) throw new InvalidUnitError("Background opacity must be finite");
  b.opacity = i.opacity;
}
if (i.rotation !== undefined) {
  if (i.rotation === null || !Number.isFinite(i.rotation)) throw new InvalidUnitError("Background rotation must be finite");
  b.rotation = i.rotation;
}
if (i.locked !== undefined && i.locked !== null) b.locked = i.locked;
u.background = b;

const i = action.input;
if (i.showLabels !== undefined && i.showLabels !== null) state.settings.showLabels = i.showLabels;
if (i.showMountHeights !== undefined && i.showMountHeights !== null) state.settings.showMountHeights = i.showMountHeights;
if (i.pipeDiameterMm !== undefined && i.pipeDiameterMm !== null) {
  if (!Number.isFinite(i.pipeDiameterMm) || i.pipeDiameterMm <= 0)
    throw new InvalidSettingsError("Pipe diameter must be positive");
  state.settings.pipeDiameterMm = i.pipeDiameterMm;
}

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = action.input.room;
if (!r.name.trim()) throw new InvalidRoomError("A room needs a name");
if (!Number.isInteger(r.labelX) || !Number.isInteger(r.labelY)) throw new InvalidRoomError("Room label coordinates must be integers");
if (r.points.length < 3) throw new InvalidRoomError("A room needs at least three points");
if (!r.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidRoomError("Room points must be finite");
if ((u.rooms ?? []).some((x) => x.id === r.id)) throw new DuplicateIdError("Room id already exists");
u.rooms = u.rooms ?? [];
u.rooms.push({
  id: r.id, name: r.name,
  points: r.points.map((p) => ({ x: p.x, y: p.y })),
  fillColor: r.fillColor ?? null,
  labelX: r.labelX, labelY: r.labelY,
  locked: r.locked ?? false,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = (u.rooms ?? []).find((x) => x.id === action.input.id);
if (!r) throw new UnknownRoomError("Unknown room");
const i = action.input;
if (i.name !== undefined && i.name !== null) {
  if (!i.name.trim()) throw new InvalidRoomError("A room needs a name");
  r.name = i.name;
}
if (i.fillColor !== undefined) r.fillColor = i.fillColor;
if (i.points !== undefined && i.points !== null) {
  if (i.points.length < 3) throw new InvalidRoomError("A room needs at least three points");
  if (!i.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidRoomError("Room points must be finite");
  r.points = i.points.map((p) => ({ x: p.x, y: p.y }));
}
if (i.labelX !== undefined && i.labelX !== null) {
  if (!Number.isFinite(i.labelX)) throw new InvalidRoomError("Room label must be finite");
  r.labelX = i.labelX;
}
if (i.labelY !== undefined && i.labelY !== null) {
  if (!Number.isFinite(i.labelY)) throw new InvalidRoomError("Room label must be finite");
  r.labelY = i.labelY;
}
if (i.locked !== undefined && i.locked !== null) r.locked = i.locked;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = (u.rooms ?? []).find((x) => x.id === action.input.id);
if (!r) throw new UnknownRoomError("Unknown room");
if ((u.fixtures ?? []).some((f) => f.roomId === r.id))
  throw new InvalidRoomError("Remove or move the fixtures in this room first");
u.rooms = (u.rooms ?? []).filter((x) => x.id !== r.id);

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const f = action.input.fixture;
if (!f.kind.trim()) throw new InvalidFixtureError("A fixture needs a kind");
if (!f.discipline.trim()) throw new InvalidFixtureError("A fixture needs a discipline");
if (!f.name.trim()) throw new InvalidFixtureError("A fixture needs a name");
if (!Number.isFinite(f.position.x) || !Number.isFinite(f.position.y)) throw new InvalidFixtureError("Fixture position must be finite");
if (!Number.isFinite(f.rotation)) throw new InvalidFixtureError("Fixture rotation must be finite");
if (f.mountHeightCm != null && (!Number.isFinite(f.mountHeightCm) || f.mountHeightCm < 0)) throw new InvalidFixtureError("Mounting height must be non-negative");
if (f.roomId != null && !(u.rooms ?? []).some((r) => r.id === f.roomId)) throw new UnknownRoomError("Unknown room");
if (u.fixtures.some((x) => x.id === f.id)) throw new DuplicateIdError("Fixture id already exists");
u.fixtures.push({
  id: f.id, kind: f.kind, discipline: f.discipline, name: f.name,
  position: { x: f.position.x, y: f.position.y }, rotation: f.rotation,
  roomId: f.roomId ?? null, mountHeightCm: f.mountHeightCm ?? null,
  notes: f.notes ?? null, locked: f.locked ?? false,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const f = u.fixtures.find((x) => x.id === action.input.id);
if (!f) throw new UnknownFixtureError("Unknown fixture");
const i = action.input;
if (i.kind !== undefined && i.kind !== null) {
  if (!i.kind.trim()) throw new InvalidFixtureError("A fixture needs a kind");
  f.kind = i.kind;
}
if (i.name !== undefined && i.name !== null) {
  if (!i.name.trim()) throw new InvalidFixtureError("A fixture needs a name");
  f.name = i.name;
}
if (i.discipline !== undefined && i.discipline !== null) {
  if (!i.discipline.trim()) throw new InvalidFixtureError("A fixture needs a discipline");
  f.discipline = i.discipline;
}
if (i.position !== undefined && i.position !== null) {
  if (!Number.isFinite(i.position.x) || !Number.isFinite(i.position.y)) throw new InvalidFixtureError("Fixture position must be finite");
  f.position = { x: i.position.x, y: i.position.y };
}
if (i.rotation !== undefined && i.rotation !== null) {
  if (!Number.isFinite(i.rotation)) throw new InvalidFixtureError("Fixture rotation must be finite");
  f.rotation = i.rotation;
}
if (i.roomId !== undefined) {
  if (i.roomId !== null && !(u.rooms ?? []).some((r) => r.id === i.roomId)) throw new UnknownRoomError("Unknown room");
  f.roomId = i.roomId;
}
if (i.mountHeightCm !== undefined) {
  if (i.mountHeightCm !== null && (!Number.isFinite(i.mountHeightCm) || i.mountHeightCm < 0)) throw new InvalidFixtureError("Mounting height must be non-negative");
  f.mountHeightCm = i.mountHeightCm;
}
if (i.notes !== undefined) f.notes = i.notes;
if (i.locked !== undefined && i.locked !== null) f.locked = i.locked;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!u.fixtures.some((x) => x.id === action.input.id)) throw new UnknownFixtureError("Unknown fixture");
u.fixtures = u.fixtures.filter((x) => x.id !== action.input.id);

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = action.input.route;
if (!r.kind.trim()) throw new InvalidPipeRouteError("A pipe needs a kind");
if (r.points.length < 2) throw new InvalidPipeRouteError("A pipe needs at least two points");
if (!r.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidPipeRouteError("Pipe points must be finite");
if (!Number.isFinite(r.diameterMm) || r.diameterMm <= 0) throw new InvalidPipeRouteError("Pipe diameter must be positive");
if (r.slopePercent != null && (!Number.isFinite(r.slopePercent) || r.slopePercent < 0 || r.slopePercent > 100)) throw new InvalidPipeRouteError("Pipe slope must be between 0 and 100 percent");
if (u.pipeRoutes.some((x) => x.id === r.id)) throw new DuplicateIdError("Pipe route id already exists");
u.pipeRoutes.push({
  id: r.id, kind: r.kind, points: r.points.map((p) => ({ x: p.x, y: p.y })),
  diameterMm: r.diameterMm, slopePercent: r.slopePercent ?? null,
  insulation: r.insulation ?? false, notes: r.notes ?? null,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = u.pipeRoutes.find((x) => x.id === action.input.id);
if (!r) throw new UnknownPipeRouteError("Unknown pipe route");
const i = action.input;
if (i.kind !== undefined && i.kind !== null) {
  if (!i.kind.trim()) throw new InvalidPipeRouteError("A pipe needs a kind");
  r.kind = i.kind;
}
if (i.points !== undefined && i.points !== null) {
  if (i.points.length < 2) throw new InvalidPipeRouteError("A pipe needs at least two points");
  if (!i.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidPipeRouteError("Pipe points must be finite");
  r.points = i.points.map((p) => ({ x: p.x, y: p.y }));
}
if (i.diameterMm !== undefined && i.diameterMm !== null) {
  if (!Number.isFinite(i.diameterMm) || i.diameterMm <= 0) throw new InvalidPipeRouteError("Pipe diameter must be positive");
  r.diameterMm = i.diameterMm;
}
if (i.slopePercent !== undefined) {
  if (i.slopePercent !== null && (!Number.isFinite(i.slopePercent) || i.slopePercent < 0 || i.slopePercent > 100)) throw new InvalidPipeRouteError("Pipe slope must be between 0 and 100 percent");
  r.slopePercent = i.slopePercent;
}
if (i.insulation !== undefined && i.insulation !== null) r.insulation = i.insulation;
if (i.notes !== undefined) r.notes = i.notes;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!u.pipeRoutes.some((x) => x.id === action.input.id)) throw new UnknownPipeRouteError("Unknown pipe route");
u.pipeRoutes = u.pipeRoutes.filter((x) => x.id !== action.input.id);

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = action.input.route;
if (!r.kind.trim()) throw new InvalidDuctRouteError("A duct needs a kind");
if (r.points.length < 2) throw new InvalidDuctRouteError("A duct needs at least two points");
if (!r.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidDuctRouteError("Duct points must be finite");
if (!Number.isFinite(r.widthMm) || r.widthMm <= 0) throw new InvalidDuctRouteError("Duct width must be positive");
if (!Number.isFinite(r.heightMm) || r.heightMm <= 0) throw new InvalidDuctRouteError("Duct height must be positive");
if (r.airflowM3h != null && (!Number.isFinite(r.airflowM3h) || r.airflowM3h < 0)) throw new InvalidDuctRouteError("Airflow must be non-negative");
if (u.ductRoutes.some((x) => x.id === r.id)) throw new DuplicateIdError("Duct route id already exists");
u.ductRoutes.push({
  id: r.id, kind: r.kind, points: r.points.map((p) => ({ x: p.x, y: p.y })),
  widthMm: r.widthMm, heightMm: r.heightMm,
  airflowM3h: r.airflowM3h ?? null, notes: r.notes ?? null,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = u.ductRoutes.find((x) => x.id === action.input.id);
if (!r) throw new UnknownDuctRouteError("Unknown duct route");
const i = action.input;
if (i.kind !== undefined && i.kind !== null) {
  if (!i.kind.trim()) throw new InvalidDuctRouteError("A duct needs a kind");
  r.kind = i.kind;
}
if (i.points !== undefined && i.points !== null) {
  if (i.points.length < 2) throw new InvalidDuctRouteError("A duct needs at least two points");
  if (!i.points.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) throw new InvalidDuctRouteError("Duct points must be finite");
  r.points = i.points.map((p) => ({ x: p.x, y: p.y }));
}
if (i.widthMm !== undefined && i.widthMm !== null) {
  if (!Number.isFinite(i.widthMm) || i.widthMm <= 0) throw new InvalidDuctRouteError("Duct width must be positive");
  r.widthMm = i.widthMm;
}
if (i.heightMm !== undefined && i.heightMm !== null) {
  if (!Number.isFinite(i.heightMm) || i.heightMm <= 0) throw new InvalidDuctRouteError("Duct height must be positive");
  r.heightMm = i.heightMm;
}
if (i.airflowM3h !== undefined) {
  if (i.airflowM3h !== null && (!Number.isFinite(i.airflowM3h) || i.airflowM3h < 0)) throw new InvalidDuctRouteError("Airflow must be non-negative");
  r.airflowM3h = i.airflowM3h;
}
if (i.notes !== undefined) r.notes = i.notes;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!u.ductRoutes.some((x) => x.id === action.input.id)) throw new UnknownDuctRouteError("Unknown duct route");
u.ductRoutes = u.ductRoutes.filter((x) => x.id !== action.input.id);

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = action.input.riser;
if (!r.kind.trim()) throw new InvalidRiserError("A riser needs a kind");
if (!Number.isFinite(r.x) || !Number.isFinite(r.y)) throw new InvalidRiserError("Riser position must be finite");
if (r.label != null && !r.label.trim()) throw new InvalidRiserError("Riser label cannot be empty");
if (u.risers.some((x) => x.id === r.id)) throw new DuplicateIdError("Riser id already exists");
u.risers.push({
  id: r.id, kind: r.kind, x: r.x, y: r.y,
  label: r.label ?? null, notes: r.notes ?? null,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = u.risers.find((x) => x.id === action.input.id);
if (!r) throw new UnknownRiserError("Unknown riser");
const i = action.input;
if (i.kind !== undefined && i.kind !== null) {
  if (!i.kind.trim()) throw new InvalidRiserError("A riser needs a kind");
  r.kind = i.kind;
}
if (i.x !== undefined && i.x !== null) {
  if (!Number.isFinite(i.x)) throw new InvalidRiserError("Riser position must be finite");
  r.x = i.x;
}
if (i.y !== undefined && i.y !== null) {
  if (!Number.isFinite(i.y)) throw new InvalidRiserError("Riser position must be finite");
  r.y = i.y;
}
if (i.label !== undefined) {
  if (i.label !== null && !i.label.trim()) throw new InvalidRiserError("Riser label cannot be empty");
  r.label = i.label;
}
if (i.notes !== undefined) r.notes = i.notes;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!u.risers.some((x) => x.id === action.input.id)) throw new UnknownRiserError("Unknown riser");
u.risers = u.risers.filter((x) => x.id !== action.input.id);
